        inc = exp = sav = 0.0
        for t in self.data["transactions"]:
            a = float(t["amount"])
            if t["kind"] == "income":
                inc += a
            elif t["kind"] == "expense":
                exp += a
            else:
                sav += a
        return {"income": inc, "expenses": exp, "savings": sav, "balance": inc - exp - sav}

